//! Commands the remote console calls: native toasts for new LINE messages and the unread badge.
use std::sync::atomic::{AtomicU32, Ordering};

use tauri::{image::Image, AppHandle, Manager, UserAttentionType};
use tauri_winrt_notification::{Sound, Toast};

use crate::{show_main, tray, MAIN};

/// Taskbar overlay icons for 1..9 and "9+" (generated by scripts/icons.mjs).
const BADGES: [&[u8]; 10] = [
    include_bytes!("../icons/badge/1.png"),
    include_bytes!("../icons/badge/2.png"),
    include_bytes!("../icons/badge/3.png"),
    include_bytes!("../icons/badge/4.png"),
    include_bytes!("../icons/badge/5.png"),
    include_bytes!("../icons/badge/6.png"),
    include_bytes!("../icons/badge/7.png"),
    include_bytes!("../icons/badge/8.png"),
    include_bytes!("../icons/badge/9.png"),
    include_bytes!("../icons/badge/9plus.png"),
];

static UNREAD: AtomicU32 = AtomicU32::new(0);

/// Shows a toast unless the agent is already looking at the console; clicking it opens the chat.
#[tauri::command]
pub fn notify(app: AppHandle, title: String, body: String, conversation_id: Option<String>) -> Result<(), String> {
    let Some(win) = app.get_webview_window(MAIN) else { return Ok(()) };
    let looking = win.is_visible().unwrap_or(false) && win.is_focused().unwrap_or(false) && !win.is_minimized().unwrap_or(true);
    if looking {
        return Ok(());
    }
    // A dev build has no installed shortcut carrying our AppUserModelID, and Windows drops toasts for unknown ids.
    let app_id = if tauri::is_dev() { Toast::POWERSHELL_APP_ID.to_string() } else { app.config().identifier.clone() };
    let handle = app.clone();
    Toast::new(&app_id)
        .title(&title)
        .text1(&body)
        .sound(Some(Sound::Default))
        .on_activated(move |_| {
            open_conversation(&handle, conversation_id.as_deref());
            Ok(())
        })
        .show()
        .map_err(|e| e.to_string())
}

fn open_conversation(app: &AppHandle, id: Option<&str>) {
    show_main(app);
    if let (Some(win), Some(id)) = (app.get_webview_window(MAIN), id) {
        // JSON-encoded so the id can't break out of the string literal.
        let path = serde_json::to_string(&format!("/inbox/{id}")).unwrap();
        let _ = win.eval(format!("location.assign({path})"));
    }
}

/// Queue count ("รอรับเรื่อง"): taskbar overlay, tray icon + tooltip, and a taskbar flash when it grows.
#[tauri::command]
pub fn set_unread(app: AppHandle, count: u32) -> Result<(), String> {
    let previous = UNREAD.swap(count, Ordering::Relaxed);
    tray::set_unread(&app, count);
    let Some(win) = app.get_webview_window(MAIN) else { return Ok(()) };
    let icon = match count {
        0 => None,
        n => Some(Image::from_bytes(BADGES[(n.min(10) - 1) as usize]).map_err(|e| e.to_string())?),
    };
    win.set_overlay_icon(icon).map_err(|e| e.to_string())?;
    if count > previous && !win.is_focused().unwrap_or(false) {
        let _ = win.request_user_attention(Some(UserAttentionType::Informational));
    }
    Ok(())
}
